def add_flow_sources(self, flow_arn: str, sources: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if flow_arn in self._flows:
        flow = self._flows[flow_arn]
        # Add source details to each new source
        for index, source in enumerate(sources):
            self._add_source_details(source, flow.id, f"127.0.1.{index}")

        # Add the new sources to the flow
        flow.sources.extend(sources)
        return flow.sources
